// Generates schema/draft/schema.json (JSON Schema 2020-12) and the schema reference pages from
// schema/draft/schema.ts, the single source. With --check, exits 1 when a generated file differs.
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import * as TJS from "typescript-json-schema";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const check = process.argv.includes("--check");
const version = "draft";
const source = join(root, "schema", version, "schema.ts");

type Schema = { [key: string]: any };

function buildSchema(): Schema {
  const program = TJS.getProgramFromFiles([source], { strict: true, skipLibCheck: true });
  const generated = TJS.generateSchema(program, "*", {
    required: true,
    noExtraProps: false,
    titles: false,
    ref: true,
    aliasRef: false,
    topRef: false,
    uniqueNames: false,
    ignoreErrors: false,
  });
  if (!generated) throw new Error("schema generation failed");
  // JSON Schema 2020-12: definitions move to $defs.
  const text = JSON.stringify(generated.definitions).replaceAll("#/definitions/", "#/$defs/");
  const defs: Schema = JSON.parse(text);
  // typescript-json-schema drops annotations on index signatures; part versions are integers.
  const version = { type: "integer", minimum: 0 };
  defs.SupportedParts.additionalProperties = { type: "array", minItems: 1, items: version };
  defs.NegotiatedParts.additionalProperties = version;
  const sorted: Schema = {};
  for (const name of Object.keys(defs).sort()) sorted[name] = defs[name];
  return {
    $schema: "https://json-schema.org/draft/2020-12/schema",
    $id: `https://agentspaceprotocol.org/schema/${version}/schema.json`,
    title: "Agent Space Protocol",
    description:
      "Every message of the Agent Space Protocol. Generated from schema.ts; do not edit by hand.",
    anyOf: [{ $ref: "#/$defs/Message" }],
    $defs: sorted,
  };
}

function typeName(s: Schema | undefined): string {
  if (!s) return "any";
  if (s.$ref) {
    const name = s.$ref.replace("#/$defs/", "");
    return `[${name}](#${name.toLowerCase()})`;
  }
  if (s.const !== undefined) return "`" + JSON.stringify(s.const) + "`";
  if (s.enum) return s.enum.map((v: unknown) => "`" + JSON.stringify(v) + "`").join(" \\| ");
  if (s.anyOf) return s.anyOf.map(typeName).join(" \\| ");
  if (Array.isArray(s.type)) return s.type.map((t: string) => "`" + t + "`").join(" \\| ");
  if (s.type === "array") return typeName(s.items) + "[]";
  if (s.type === "object" && s.additionalProperties && typeof s.additionalProperties === "object" && !s.properties)
    return "map of " + typeName(s.additionalProperties);
  if (s.type) return "`" + s.type + "`";
  return "any";
}

function oneLine(text: string | undefined): string {
  return (text ?? "").replace(/\r?\n\s*\r?\n/g, "<br><br>").replace(/\r?\n/g, " ").replaceAll("|", "\\|");
}

function buildReference(schema: Schema): string {
  const defs = schema.$defs as Schema;
  const messages = new Set<string>();
  for (const union of ["ParticipantMessage", "SpaceMessage"]) {
    for (const m of defs[union].anyOf) messages.add(m.$ref.replace("#/$defs/", ""));
  }
  const lines: string[] = [
    "---",
    "title: Schema reference",
    "description: Every message and type of the Agent Space Protocol, generated from schema.ts.",
    "---",
    "",
    "<!-- Generated by scripts/generate.ts from schema/draft/schema.ts. Do not edit by hand. -->",
    "",
    "This page is generated from [`schema/draft/schema.ts`](https://github.com/agent-space-protocol/agentspaceprotocol/blob/main/schema/draft/schema.ts), the single source of the protocol's messages. The same source produces [`schema.json`](https://github.com/agent-space-protocol/agentspaceprotocol/blob/main/schema/draft/schema.json). Every object accepts members it does not list: unknown fields must be ignored and passed on unchanged.",
    "",
  ];
  const section = (title: string, names: string[]) => {
    lines.push(`## ${title}`, "");
    for (const name of names) {
      const d = defs[name];
      lines.push(`### ${name}`, "");
      if (d.description) lines.push(d.description.trim(), "");
      if (d.properties) {
        lines.push("| Field | Type | Required | Description |", "| --- | --- | --- | --- |");
        const required = new Set(d.required ?? []);
        for (const [field, ps] of Object.entries<Schema>(d.properties)) {
          lines.push(`| \`${field}\` | ${typeName(ps)} | ${required.has(field) ? "yes" : ""} | ${oneLine(ps.description)} |`);
        }
        lines.push("");
      } else if (d.anyOf || d.enum || d.type) {
        lines.push(`Type: ${typeName(d)}`, "");
        if (d.pattern) lines.push(`Pattern: \`${d.pattern}\``, "");
      }
    }
  };
  const participantMsgs = defs.ParticipantMessage.anyOf.map((m: Schema) => m.$ref.replace("#/$defs/", ""));
  const spaceMsgs = defs.SpaceMessage.anyOf.map((m: Schema) => m.$ref.replace("#/$defs/", ""));
  section("Messages from participants", participantMsgs);
  section("Messages from spaces", spaceMsgs);
  const rest = Object.keys(defs).filter((n) => !messages.has(n) && !["Message", "ParticipantMessage", "SpaceMessage"].includes(n));
  section("Types", rest);
  return lines.join("\n");
}

function emit(path: string, content: string): boolean {
  const old = existsSync(path) ? readFileSync(path, "utf8") : undefined;
  if (old === content) return true;
  if (check) {
    console.error(`out of date: ${path.slice(root.length + 1)} (run pnpm generate)`);
    return false;
  }
  writeFileSync(path, content);
  console.log(`wrote ${path.slice(root.length + 1)}`);
  return true;
}

const schema = buildSchema();
let ok = emit(join(root, "schema", version, "schema.json"), JSON.stringify(schema, null, 2) + "\n");
ok = emit(join(root, "docs", "en", "reference", "schema.md"), buildReference(schema) + "\n") && ok;
if (!ok) process.exit(1);
if (check) console.log("generated files are up to date");
